package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's
 * claimed-total and due-total. A change takes a snapshot before it and, once its own audit lines are
 * written, records a ROLLUP line per person whose figures moved and a TOTALS line when the totals did.
 */
@Service
public class RollupService {

    /** A person's figures, as text with two decimals; the due-total is "n/a" when they have none. */
    public record Figures(String name, String claimed, String dueTotal) {}

    /** Each person's figures by id, in the order they were added, and the sheet's totals. */
    public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal) {}

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /**
     * The sheet's figures now. Only open and settled claims count (a held person's open ones do not); a person's due-total is the sum of
     * their figures (those with one), n/a when their grade has no rate in force on the sheet's today
     * and no counting claim of theirs keeps a fixed (settled or stated) figure.
     */
    @Transactional(readOnly = true)
    public Rollup snapshot(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElseGet(LocalDate::now);
        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .filter(c -> c.getStatus().counts())
                .collect(Collectors.groupingBy(Claim::getPersonId));
        Map<Long, Figures> out = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> counted = byPerson.getOrDefault(p.getId(), List.of()).stream()
                    .filter(c -> counts(p, c))
                    .toList();
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            for (Claim c : counted) {
                claimed = claimed.add(c.getAmount());
                BigDecimal figure = figure(sheetId, p, c);
                if (figure != null) due = due.add(figure);
            }
            boolean rated = rates.findInForce(sheetId, p.getGrade(), today).isPresent();
            boolean anyFixed = counted.stream().anyMatch(Claim::keepsFigure);
            claimedTotal = claimedTotal.add(claimed);
            if (rated || anyFixed) dueTotal = dueTotal.add(due);
            out.put(p.getId(), new Figures(p.getName(), text(claimed), rated || anyFixed ? text(due) : "n/a"));
        }
        return new Rollup(out, text(claimedTotal), text(dueTotal));
    }

    /**
     * Whether a claim counts in the live totals: open and settled claims do, except the open claims
     * of a person on hold.
     */
    public static boolean counts(Person person, Claim claim) {
        return claim.getStatus().counts() && !(person.isHeld() && claim.getStatus() == ClaimStatus.OPEN);
    }

    /**
     * Record, once the change commits, a ROLLUP line for each person whose figures moved since
     * {@code before} (a person who did not exist then counts as moved), then a TOTALS line when the
     * sheet's totals moved.
     */
    @Transactional(readOnly = true)
    public void recordChanges(String sheetId, String user, Rollup before) {
        Rollup after = snapshot(sheetId);
        List<String> lines = new ArrayList<>();
        after.people().forEach((id, now) -> {
            Figures was = before.people().get(id);
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())) {
                lines.add("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal());
            }
        });
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
            lines.add("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal());
        }
        lines.forEach(audit::recordOnCommit);
    }

    /**
     * The figure a claim shows: a settled claim's fixed due (any late charge frozen in), else its
     * bound figure (see {@link #boundFigure}) with, when it is overdue, its late charge on top; null
     * when none.
     */
    @Transactional(readOnly = true)
    public BigDecimal figure(String sheetId, Person person, Claim claim) {
        if (claim.getDue() != null) return claim.getDue();
        BigDecimal figure = boundFigure(sheetId, person, claim);
        if (figure == null) return null;
        return sheets.findById(sheetId).map(sheet -> figure.add(lateCharge(sheet, claim, figure))).orElse(figure);
    }

    /**
     * The figure a statement binds a live claim to, without any late charge: the figure its person's
     * last statement bound it to, else its amount times the rate in force on its date, raised to the
     * sheet's floor; null when none.
     */
    @Transactional(readOnly = true)
    public BigDecimal boundFigure(String sheetId, Person person, Claim claim) {
        if (claim.isStated()) return claim.getStatedDue();
        BigDecimal floor = sheets.findById(sheetId).map(Sheet::getFloor).orElse(BigDecimal.ZERO);
        return rates.findInForce(sheetId, person.getGrade(), claim.getDate())
                .map(rate -> due(claim.getAmount(), rate).max(floor).setScale(2))
                .orElse(null);
    }

    /**
     * An overdue claim's late charge on a figure: the sheet's late percent of it for every full 30
     * days the claim is overdue (open, due by its date plus the terms, before the sheet's today),
     * rounded like due; zero when it is not overdue.
     */
    private static BigDecimal lateCharge(Sheet sheet, Claim claim, BigDecimal figure) {
        if (claim.getStatus() != ClaimStatus.OPEN) return BigDecimal.ZERO;
        long daysOver = ChronoUnit.DAYS.between(claim.getDate().plusDays(sheet.getTerms()), sheet.getToday());
        if (daysOver <= 0) return BigDecimal.ZERO;
        BigDecimal pct = sheet.getLatePct().multiply(BigDecimal.valueOf(daysOver / 30));
        return figure.multiply(pct).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
    }

    /** The amount times the rate's percent, rounded half to even to cents (as the screen works it out). */
    private static BigDecimal due(BigDecimal amount, Rate rate) {
        return amount.multiply(rate.getPct()).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
    }

    private static String text(BigDecimal amount) {
        return amount.setScale(2).toPlainString();
    }
}
import { Component, computed, effect, inject, signal, untracked } from '@angular/core';
import { finalize, switchMap } from 'rxjs';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { GRADES, Grade, PeopleService, Person } from '../../core/people.service';
import { SheetService } from '../../core/sheet.service';
import { ClaimsService, claimDue, fixed, money, overdue } from '../../core/claims.service';
import { RatesService } from '../../core/rates.service';
import { SettingsService } from '../../core/settings.service';
import { PersonClaims } from './person-claims';

// The sheet's people: a form that adds a person or edits the one opened, and the list with each
// person's claims, claimed and due-total, and the sheet's claimed total and due-total. A due-total
// is the sum of the person's open and settled claims' (already rounded) dues, 0.00 with none; a
// person whose grade has no rate in force on the sheet's today has no due-total (n/a) unless a
// settled or stated claim of theirs keeps a fixed figure. The sheet's due-total skips those with none.
// Each person has a statement button: it records their due-total and binds their counting claims to
// their figures then; the row shows how many statements were taken, and the last one's due-total and date.
// A person can be retired from a date (the sheet's today when none is entered). Retired people are
// left out of the list unless "show retired" is on; their claims keep counting in every total.
// A person can be put on hold and taken off it again: while held, their open claims count in no
// live total (settled ones still do).
// Each person, and the sheet, shows how many of their counting claims are overdue (open, due by
// before the sheet's today) and those claims' dues added up (a claim with none adds nothing).
@Component({
  selector: 'app-people',
  imports: [ReactiveFormsModule, PersonClaims],
  template: `
    <section aria-labelledby="people-heading">
      <h2 id="people-heading">People</h2>
      <form [formGroup]="form" (ngSubmit)="submit()" [attr.aria-label]="editing() === null ? 'Add person' : 'Edit person'">
        <label for="person-form-name">Name</label>
        <input id="person-form-name" data-testid="person-form-name" formControlName="name" />
        <label for="person-form-grade">Grade</label>
        <select id="person-form-grade" data-testid="person-form-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <button type="submit" data-testid="person-form-submit">{{ editing() === null ? 'Add' : 'Save' }}</button>
        @if (editing() !== null) {
          <button type="button" data-testid="person-form-cancel" (click)="reset()">Cancel</button>
        }
        @if (error()) {
          <p role="alert" data-testid="person-form-error">{{ error() }}</p>
        }
      </form>
      <form [formGroup]="quick" (ngSubmit)="quickAdd()" aria-label="Quick add a draft claim">
        <label for="quick-name">Name</label>
        <input id="quick-name" data-testid="quick-name" formControlName="name" />
        <label for="quick-amount">Amount</label>
        <input id="quick-amount" data-testid="quick-amount" formControlName="amount" inputmode="decimal" />
        <button type="submit" data-testid="quick-submit">Quick add</button>
        @if (quickError()) {
          <p role="alert" data-testid="quick-error">{{ quickError() }}</p>
        }
      </form>
      <p>
        <input type="checkbox" id="show-retired" data-testid="show-retired"
          [checked]="people.showRetired()" (change)="people.showRetired.set($any($event.target).checked)" />
        <label for="show-retired">Show retired</label>
      </p>
      <table>
        <thead>
          <tr>
            <th scope="col">Name</th><th scope="col">Grade</th><th scope="col">Claimed</th><th scope="col">Due</th>
            <th scope="col">Statements</th><th scope="col">Last stated</th><th scope="col">Stated on</th>
            <th scope="col">Retired</th><th scope="col">Retired from</th><th scope="col">On hold</th>
            <th scope="col">Overdue</th><th scope="col">Overdue due</th>
            <th scope="col"><span class="visually-hidden">Actions</span></th><th scope="col">Claims</th>
          </tr>
        </thead>
        <tbody>
          @for (p of listed(); track p.id) {
            <tr [attr.data-testid]="'person-row-' + p.id">
              <td data-testid="person-name">{{ p.name }}</td>
              <td data-testid="person-grade">{{ p.grade }}</td>
              <td data-testid="person-claimed">{{ money(claims.claimedCents().get(p.id) ?? 0) }}</td>
              <td data-testid="person-due-total">{{ amountOrNa(dueTotals().get(p.id)) }}</td>
              <td data-testid="person-statement-count">{{ p.statementCount }}</td>
              <td data-testid="person-stated-total">{{ p.statedTotal ?? '' }}</td>
              <td data-testid="person-statement-date">{{ p.statementDate ?? '' }}</td>
              <td data-testid="person-retired">{{ p.retiredFrom ? 'yes' : 'no' }}</td>
              <td data-testid="person-retired-from">{{ p.retiredFrom ?? '' }}</td>
              <td data-testid="person-hold">{{ p.held ? 'yes' : 'no' }}</td>
              <td data-testid="person-overdue-count">{{ overdueOf(p.id).count }}</td>
              <td data-testid="person-overdue-total">{{ money(overdueOf(p.id).cents) }}</td>
              <td>
                <button type="button" [attr.data-testid]="'person-edit-' + p.id" (click)="open(p)"
                  [attr.aria-label]="'Edit ' + p.name">Edit</button>
                <button type="button" data-testid="person-statement" (click)="statement(p)"
                  [attr.aria-label]="'Take a statement for ' + p.name">Statement</button>
                <label [for]="'person-retire-date-' + p.id">Retire from</label>
                <input type="date" [id]="'person-retire-date-' + p.id" data-testid="person-retire-date"
                  #retireDate (input)="setRowError(p.id, '')" />
                <button type="button" data-testid="person-retire" (click)="retire(p, retireDate.value)"
                  [attr.aria-label]="'Retire ' + p.name">Retire</button>
                <button type="button" data-testid="person-hold-toggle" (click)="toggleHold(p)"
                  [attr.aria-label]="(p.held ? 'Release ' : 'Hold ') + p.name">{{ p.held ? 'Release' : 'Hold' }}</button>
                @if (rowErrors().get(p.id); as e) {
                  <p role="alert" data-testid="person-error">{{ e }}</p>
                }
              </td>
              <td><app-person-claims [personId]="p.id" [personName]="p.name" [grade]="p.grade" /></td>
            </tr>
          }
        </tbody>
      </table>
      <p>Claimed in total: <span data-testid="rollup-claimed-total">{{ money(claims.totalCents()) }}</span></p>
      <p>Due in total: <span data-testid="rollup-due-total">{{ money(dueTotal()) }}</span></p>
      <p>Overdue claims: <span data-testid="rollup-overdue-count">{{ overdueTotal().count }}</span></p>
      <p>Overdue in total: <span data-testid="rollup-overdue-total">{{ money(overdueTotal().cents) }}</span></p>
    </section>
  `,
})
export class People {
  protected readonly people = inject(PeopleService);
  protected readonly claims = inject(ClaimsService);
  private readonly rates = inject(RatesService);
  private readonly sheets = inject(SheetService);
  private readonly settings = inject(SettingsService);
  protected readonly money = money;
  protected readonly grades = GRADES;
  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
    grade: new FormControl<Grade>('A', { nonNullable: true }),
  });
  /** The quick-add bar: a draft claim for a named person, added with grade A when not on the sheet. */
  protected readonly quick = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
    amount: new FormControl('', { nonNullable: true }),
  });
  protected readonly quickError = signal('');
  /** A quick add is waiting for its answer; another meanwhile is ignored. */
  private quickSaving = false;
  protected readonly editing = signal<number | null>(null);
  /** The version of the person being edited that the form loaded. */
  private loadedVersion = 0;
  /** A submit is waiting for its answer; another submit meanwhile is ignored. */
  private saving = false;
  protected readonly error = signal('');
  /** Each person's refused row action, by person id; cleared by the next action on that row. */
  protected readonly rowErrors = signal<ReadonlyMap<number, string>>(new Map());
  /** The people listed: retired ones only when "show retired" is on. */
  protected readonly listed = computed(() => this.people.showRetired()
    ? this.people.people()
    : this.people.people().filter((p) => !p.retiredFrom));
  /**
   * Each person's due-total in cents: the sum of their open and settled claims' dues (those with one);
   * absent when their grade has no rate in force today and no settled or stated claim of theirs keeps a figure.
   */
  protected readonly dueTotals = computed(() => {
    const out = new Map<number, number>();
    const floor = this.settings.floorCents();
    const late = this.settings.late();
    for (const p of this.people.people()) {
      const counted = (this.claims.byPerson().get(p.id) ?? []).filter(this.claims.live());
      if (!this.rates.byGrade().has(p.grade) && !counted.some(fixed)) continue;
      const rateOn = (date: string) => this.rates.rateOn(p.grade, date);
      out.set(p.id, counted.reduce((sum, c) => sum + (claimDue(c, rateOn, floor, late) ?? 0), 0));
    }
    return out;
  });
  /** Everyone's due-total added up, in cents, skipping those with none. */
  protected readonly dueTotal = computed(() => [...this.dueTotals().values()].reduce((sum, d) => sum + d, 0));

  /** Each person's overdue claims that count: how many, and their dues (late charges in) added up in cents. */
  protected readonly overdue = computed(() => {
    const out = new Map<number, { count: number; cents: number }>();
    const floor = this.settings.floorCents();
    const late = this.settings.late();
    const terms = this.settings.terms();
    const today = this.sheets.today();
    for (const p of this.people.people()) {
      const behind = (this.claims.byPerson().get(p.id) ?? [])
        .filter(this.claims.live())
        .filter((c) => overdue(c, terms, today));
      const rateOn = (date: string) => this.rates.rateOn(p.grade, date);
      out.set(p.id, {
        count: behind.length,
        cents: behind.reduce((sum, c) => sum + (claimDue(c, rateOn, floor, late) ?? 0), 0),
      });
    }
    return out;
  });
  /** Everyone's overdue claims that count: how many, and their dues added up in cents. */
  protected readonly overdueTotal = computed(() => [...this.overdue().values()].reduce(
    (sum, o) => ({ count: sum.count + o.count, cents: sum.cents + o.cents }), { count: 0, cents: 0 }));

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    this.quick.valueChanges.subscribe(() => this.quickError.set(''));
    effect(() => {
      this.sheets.loads();
      untracked(() => {
        this.reset();
        this.quickError.set('');
        this.quick.reset({ name: '', amount: '' }, { emitEvent: false });
      });
    });
  }

  protected overdueOf(personId: number): { count: number; cents: number } {
    return this.overdue().get(personId) ?? { count: 0, cents: 0 };
  }

  protected amountOrNa(cents: number | undefined): string {
    return cents === undefined ? 'n/a' : money(cents);
  }

  /** Take a statement for the person, then re-read the people to show its count, due-total and date. */
  protected statement(p: Person): void {
    this.setRowError(p.id, '');
    this.claims.statement(p.id).pipe(switchMap(() => this.people.reload())).subscribe({
      error: () => this.setRowError(p.id, 'Could not take a statement for ' + p.name + '.'),
    });
  }

  /** Retire the person from the date entered, or from the sheet's today when none is. */
  protected retire(p: Person, from: string): void {
    this.setRowError(p.id, '');
    this.people.retire(p.id, from.trim() || null).subscribe({
      error: () => this.setRowError(p.id, 'Could not retire ' + p.name + '.'),
    });
  }

  /** Put the person on hold, or take them off it. */
  protected toggleHold(p: Person): void {
    this.setRowError(p.id, '');
    this.people.toggleHold(p.id).subscribe({
      error: () => this.setRowError(p.id, 'Could not change the hold on ' + p.name + '.'),
    });
  }

  protected setRowError(personId: number, message: string): void {
    this.rowErrors.update((all) => {
      const out = new Map(all);
      if (message) out.set(personId, message);
      else out.delete(personId);
      return out;
    });
  }

  /** Add the draft claim, then re-read the people to show one added for it. */
  protected quickAdd(): void {
    if (this.quickSaving) return;
    this.quickError.set('');
    const { name, amount } = this.quick.getRawValue();
    if (!name.trim()) {
      this.quickError.set('Enter a name.');
      return;
    }
    this.quickSaving = true;
    this.claims.quickAdd(name, amount.trim()).pipe(
      switchMap(() => this.people.reload()),
      finalize(() => (this.quickSaving = false)),
    ).subscribe({
      next: () => this.quick.reset({ name: '', amount: '' }, { emitEvent: false }),
      error: (e: { status?: number }) => this.quickError.set(
        e.status === 400 ? 'Enter a name and an amount of 0.00 or more with up to two decimals.'
          : e.status === 409 ? 'That claim could not be added: its date or name is not allowed.'
          : 'Could not add that claim.',
      ),
    });
  }

  protected open(p: Person): void {
    this.error.set('');
    this.editing.set(p.id);
    this.loadedVersion = p.version;
    this.form.setValue({ name: p.name, grade: p.grade }, { emitEvent: false });
  }

  protected reset(): void {
    this.error.set('');
    this.editing.set(null);
    this.form.reset({ name: '', grade: 'A' }, { emitEvent: false });
  }

  protected submit(): void {
    if (this.saving) return;
    this.error.set('');
    const { name, grade } = this.form.getRawValue();
    if (!name.trim()) {
      this.error.set('Enter a name.');
      return;
    }
    const id = this.editing();
    const saved = id === null
      ? this.people.add({ name, grade })
      : this.people.edit(id, this.loadedVersion, { name, grade });
    this.saving = true;
    saved.pipe(finalize(() => (this.saving = false))).subscribe({
      next: () => this.reset(),
      error: (e: { status?: number }) => {
        if (id !== null && e.status === 412) {
          this.showCurrent(id);
          return;
        }
        this.error.set(
          e.status === 409
            ? 'That name is already in use.'
            : id === null ? 'Could not add that person.' : 'Could not save that person.',
        );
      },
    });
  }

  /** Someone else saved the person being edited: refuse, and show what the store holds now. */
  private showCurrent(id: number): void {
    const message = 'Someone else has saved this person since you opened it. Their values are shown now.';
    this.error.set(message);
    this.people.reload().subscribe({
      next: () => {
        const p = this.people.people().find((o) => o.id === id);
        if (this.editing() !== id || !p) return;
        this.loadedVersion = p.version;
        this.form.setValue({ name: p.name, grade: p.grade }, { emitEvent: false });
        this.error.set(message);
      },
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, of, tap } from 'rxjs';
import { SessionService } from './session.service';
import { SheetService } from './sheet.service';

export type Grade = 'A' | 'B' | 'C';

export const GRADES: readonly Grade[] = ['A', 'B', 'C'];

export interface Person {
  id: number;
  name: string;
  grade: Grade;
  /** Moved on by every save; an edit names the version it was made from. */
  version: number;
  /** How many statements were taken for them. */
  statementCount: number;
  /** The last statement's due-total, as text with two decimals ("n/a" when it had none); null before the first. */
  statedTotal: string | null;
  /** The sheet's today (yyyy-MM-dd) when the last statement was taken; null before the first. */
  statementDate: string | null;
  /** Retired from this date (yyyy-MM-dd): claims dated after it are refused; null when not retired. */
  retiredFrom: string | null;
  /** On hold: their open claims count in no live total (settled ones still do). */
  held: boolean;
}

export interface PersonForm {
  name: string;
  grade: Grade;
}

// The active sheet's people, in the order they were added.
@Injectable({ providedIn: 'root' })
export class PeopleService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly list = signal<Person[]>([]);

  readonly people = this.list.asReadonly();
  /** Whether retired people are listed: off when the screen opens, left as it is by loading a sheet. */
  readonly showRetired = signal(false);

  /** Re-read the active sheet's people from the store. */
  reload(): Observable<unknown> {
    const id = this.sheets.sheetId();
    if (!id) {
      this.list.set([]);
      return of(null);
    }
    return this.http
      .get<Person[]>(this.url(id), { headers: this.session.headers() })
      .pipe(tap((people) => {
        if (this.sheets.sheetId() === id) this.list.set(people);
      }));
  }

  add(form: PersonForm): Observable<Person> {
    return this.http
      .post<Person>(this.url(this.sheet()), form, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => [...all, p])));
  }

  /** Save the person from the version the editor loaded; refused (412) when someone saved them since. */
  edit(personId: number, version: number, form: PersonForm): Observable<Person> {
    return this.http
      .put<Person>(`${this.url(this.sheet())}/${personId}`, { ...form, version }, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => all.map((o) => (o.id === p.id ? p : o)))));
  }

  /** Retire the person from a date (yyyy-MM-dd); without one, from the sheet's today. */
  retire(personId: number, from: string | null): Observable<Person> {
    return this.http
      .post<Person>(`${this.url(this.sheet())}/${personId}/retire`, { from }, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => all.map((o) => (o.id === p.id ? p : o)))));
  }

  /** Put the person on hold, or take them off hold when they are held. */
  toggleHold(personId: number): Observable<Person> {
    return this.http
      .post<Person>(`${this.url(this.sheet())}/${personId}/hold`, null, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => all.map((o) => (o.id === p.id ? p : o)))));
  }

  private sheet(): string {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return id;
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/people`;
  }
}

